143	  wore: boolean,
144	): Promise<void> {
145	  const supabase = await createClient();
146	  const {
147	    data: { user },
148	  } = await supabase.auth.getUser();
149	  if (!user) return;
150	
151	  const { data: profile } = await supabase
152	    .from("profiles")
153	    .select("preferences, location_timezone")
154	    .eq("id", user.id)
155	    .single();
156	
157	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
158	
159	  // Mark the question answered FIRST. If the wear write then fails, the user is
160	  // not re-asked tonight — better a missed log than a sheet that keeps
161	  // reappearing until they answer the way it wants.
162	  const next = { ...readPreferences(profile?.preferences), wearAskedOn: today };
163	  await supabase.from("profiles").update({ preferences: next }).eq("id", user.id);
164	
165	  if (wore) await toggleWear(outfitId);
166	
167	  revalidatePath("/generate");
168	}
