30	  }
31	
32	  return (
33	    <WearConfirmSheet
34	      open={open}
35	      lookName={lookName}
36	      pending={pending}
37	      onYes={() => answer(true)}
38	      onNo={() => answer(false)}
39	      // Records NOTHING — the question stays askable, so a mis-tap does not
40	      // silently consume the day's only chance to log the wear.
41	      onDismiss={() => setOpen(false)}
42	    />
43	  );
