1	/**
2	 * The user's local calendar date, as `YYYY-MM-DD`.
3	 *
4	 * This is the key of the daily look set. It must be LOCAL: keyed on the UTC
5	 * date, the drop would roll over mid-evening for eastern users and mid-morning
6	 * for western ones. `en-CA` is used purely because it formats as YYYY-MM-DD.
7	 */
8	export function localDateFor(now: Date, timeZone: string): string {
9	  try {
10	    return new Intl.DateTimeFormat("en-CA", {
11	      timeZone,
12	      year: "numeric",
13	      month: "2-digit",
14	      day: "2-digit",
15	    }).format(now);
16	  } catch {
17	    // An unknown zone must never block generation — fall back to UTC.
18	    return now.toISOString().slice(0, 10);
19	  }
20	}
21	
22	/**
23	 * The user's local hour, 0–23.
24	 *
25	 * Same reasoning as `localDateFor`, and the same fallback: the evening
26	 * confirmation asks after 18:00 LOCAL, so a UTC hour would put the question in
27	 * the afternoon for eastern users and after midnight for western ones.
28	 *
29	 * `hourCycle: "h23"` because the default for some locales is `h24`, which
30	 * renders midnight as "24" and would parse to an hour that never compares less
31	 * than the evening threshold.
32	 */
33	export function localHourFor(now: Date, timeZone: string): number {
34	  try {
35	    const hh = new Intl.DateTimeFormat("en-GB", {
36	      timeZone,
37	      hour: "2-digit",
38	      hourCycle: "h23",
39	    }).format(now);
40	    return Number(hh);
41	  } catch {
42	    return now.getUTCHours();
43	  }
44	}
